const toolBar=document.createElement('div');toolBar.className='searchbar';toolBar.innerHTML='<form id="searchform"><input id="searchinput" maxlength="80" type="search" aria-label="Location search" required minlength="2"><button id="searchbutton" type="submit">⌕</button></form><button id="imagery">NASA</button><input type="date" id="imageDate" aria-label="Satellite imagery date"><div id="searchresults" aria-live="polite"></div><small id="imageStatus" aria-live="polite"></small>';document.querySelector('.global-location').after(toolBar);toolBar.classList.add('global-search');toolBar.hidden=true;const manual=document.createElement('form');manual.id='manual-coords';manual.innerHTML='<input id="manualLat" type="number" min="-90" max="90" step="any" required aria-label="Latitude" placeholder="Latitude"><input id="manualLon" type="number" min="-180" max="180" step="any" required aria-label="Longitude" placeholder="Longitude"><button id="manualApply" type="submit">OK</button>';toolBar.append(manual);const imageControls=document.createElement('div');imageControls.className='imagery-controls';imageControls.append($('imagery'),$('imageDate'),$('imageStatus'));document.querySelector('.maphead').after(imageControls);$('locationEdit').onclick=()=>{toolBar.hidden=!toolBar.hidden;if(!toolBar.hidden)$('searchinput').focus();};manual.onsubmit=e=>{e.preventDefault();const lat=Number($('manualLat').value),lon=Number($('manualLon').value);if(validCoords(lon,lat)){selectPosition(lon,lat);if(mapReady)map.flyTo({center:[lon,lat],zoom:6});toolBar.hidden=true;}};
$('imageDate').value=new Date(Date.now()-2*86400000).toISOString().slice(0,10);$('imageDate').max=new Date().toISOString().slice(0,10);$('imageDate').min='2000-02-24';
let searchResults=[],searchSequence=0,imagery=false;
$('searchform').onsubmit=async e=>{e.preventDefault();let seq=++searchSequence;$('searchresults').textContent=tr('جارٍ البحث…','Searching…');try{const found=await geocode($('searchinput').value,state.lang);if(seq!==searchSequence)return;searchResults=found;$('searchresults').innerHTML=found.length?found.map((x,i)=>'<button data-place="'+i+'">'+safe([x.name,x.admin,x.country].filter(Boolean).join(' · '))+'</button>').join(''):tr('لا نتائج','No matches');}catch{$('searchresults').textContent=tr('تعذر البحث','Search unavailable');}};
$('searchresults').addEventListener('click',e=>{let id=e.target.closest('[data-place]')?.dataset.place;if(id!==undefined&&searchResults[id]){let x=searchResults[id];selectPosition(x.lon,x.lat,x.name);if(mapReady)map.flyTo({center:[x.lon,x.lat],zoom:5});$('searchresults').textContent='';toolBar.hidden=true;}});
function setImagery(){if(!mapReady){$('imageStatus').textContent=tr('الخريطة غير جاهزة','Map not ready');return;}try{if(map.getLayer('satellite'))map.removeLayer('satellite');if(map.getSource('satellite'))map.removeSource('satellite');if(imagery){map.addSource('satellite',{type:'raster',tiles:gibsTiles($('imageDate').value),tileSize:256,maxzoom:9,attribution:'NASA EOSDIS GIBS · MODIS Terra'});map.addLayer({id:'satellite',type:'raster',source:'satellite',paint:{'raster-opacity':1}},'quakes');$('imageStatus').textContent=tr('صور NASA MODIS اليومية؛ تاريخ الطلب ','NASA MODIS daily imagery; requested date ')+$('imageDate').value;}else $('imageStatus').textContent='';$('imagery').classList.toggle('active',imagery);}catch{ $('imageStatus').textContent=tr('الصور غير متاحة','Imagery unavailable'); }}
$('imagery').onclick=()=>{imagery=!imagery;setImagery();};$('imageDate').onchange=()=>{if(imagery)setImagery();};
let map, mapReady=false,mapAttempted=false;
async function ensureMap(){if(mapAttempted)return;mapAttempted=true;try{const maplibregl=await import('maplibre-gl');maplibregl.setWorkerUrl(new URL(workerUrl,location.href).href);
 map=new maplibregl.Map({container:'map',style:{version:8,sources:{land:{type:'geojson',data:import.meta.env.BASE_URL+'land.geojson'},events:{type:'geojson',data:{type:'FeatureCollection',features:[]}},selection:{type:'geojson',data:{type:'FeatureCollection',features:[]}},measure:{type:'geojson',data:{type:'FeatureCollection',features:[]}}},layers:[{id:'ocean',type:'background',paint:{'background-color':'#102d43'}},{id:'land',type:'fill',source:'land',paint:{'fill-color':'#38665e','fill-outline-color':'#6a9b88'}},{id:'quakes',type:'circle',source:'events',paint:{'circle-color':['get','color'],'circle-radius':['interpolate',['linear'],['zoom'],0,3,6,7,12,10],'circle-stroke-width':1,'circle-stroke-color':'#ffe8c8','circle-opacity':0.82}},{id:'measureline',type:'line',source:'measure',paint:{'line-color':'#fff09a','line-width':3}},{id:'selection',type:'circle',source:'selection',paint:{'circle-color':'#45f4d4','circle-radius':7,'circle-stroke-color':'#fff','circle-stroke-width':2}}]},center:[state.position.lon,state.position.lat],zoom:1.35,attributionControl:{compact:true}});
 map.addControl(new maplibregl.NavigationControl(),'bottom-left');
 map.addControl(new maplibregl.AttributionControl({customAttribution:'Natural Earth • public domain | USGS • NASA • NOAA'}),'bottom-right');
 map.on('load',()=>{mapReady=true;if(imagery)setImagery();map.setProjection({type:state.mode==='flat'?'mercator':'globe'});updateMap();});
 map.on('error',e=>{if(imagery){$('imageStatus').textContent=tr('بعض مربعات صور NASA قد تكون غير متاحة','Some NASA imagery tiles may be unavailable');}if(!mapReady){$('maperror').hidden=false;$('maperror').textContent=tr('تعذر تحميل الخريطة. البيانات النصية متاحة.','Map loading failed. Text data remains available.');}});
 map.on('click',e=>{if(!validCoords(e.lngLat.lng,e.lngLat.lat))return;const found=map.queryRenderedFeatures(e.point,{layers:['quakes']})[0];if(found&&!state.measure){const item=state.events.find(x=>x.id===found.properties.id);if(item){showEvent(item);return;}}selectPosition(e.lngLat.lng,e.lngLat.lat);});
}catch(e){$('maperror').hidden=false;$('maperror').textContent='WebGL unavailable / تعذر تشغيل الخرائط';}}
function visibleEvents(){const f=state.filter,all=[...new Map([...state.events,...state.history].map(e=>[e.id,e])).values()];return eventsAt(all,state.at).filter(e=>state.layers[e.category==='earthquake'?'earthquake':e.category==='wildfires'?'wildfires':'other']&&(f.category==='all'||e.category===f.category)&&Date.parse(e.time)>=state.at-f.hours*3600000&&(!f.magnitude||e.category!=='earthquake'||e.magnitude>=f.magnitude)&&(!f.radius||distance(state.position,e)<=f.radius));}
function updateMap(){if(!mapReady)return;map.getSource('events').setData({type:'FeatureCollection',features:visibleEvents().map(e=>({type:'Feature',geometry:{type:'Point',coordinates:[e.lon,e.lat]},properties:{id:e.id,color:colors[e.category]||colors.other}}))});map.getSource('selection').setData({type:'FeatureCollection',features:[{type:'Feature',geometry:{type:'Point',coordinates:[state.position.lon,state.position.lat]},properties:{}}]});map.getSource('measure').setData({type:'FeatureCollection',features:state.points.length>=2?[{type:'Feature',geometry:{type:'LineString',coordinates:[...state.points,...(state.areaMode&&state.points.length>=3?[state.points[0]]:[])].map(p=>[p.lon,p.lat])},properties:{}}]:[]});}
function selectPosition(lon,lat,name=''){if(!validCoords(lon,lat))return;if(state.measure){if(!state.areaMode&&state.points.length===2)state.points=[];if(state.points.length<500)state.points.push({lon,lat});updateMap();renderChrome();return;}state.position={lon,lat};state.locationName=name;updateMap();renderChrome();loadPosition();}
function showEvent(e){state.tab='disasters';state.selected=e;if(mapReady)map.flyTo({center:[e.lon,e.lat],zoom:4,duration:700});render();}
